public LabController(LabAdapter adapter,string target)
{
    this.adapter=adapter; this.target=target;
    adapter.Completed+=OnCompleted;
}
public void Dispose()
{
    if(closed)return;
    closed=true;
    adapter.Completed-=OnCompleted;
}
// LabAdapter.SubscriberCount reads Completed.GetInvocationList().Length.
// It is an observation of the event list, not a fixed expected number.
